class Solution:

	def util(self, o, c, s, ans):
		if o < 0 or c < 0:
			return
		if o == 0 and c == 0:
			ans.append(s)
			return
		if o == c:
			self.util(o - 1, c, s + '(', ans)
		else:
			self.util(o - 1, c, s + '(', ans)
			self.util(o, c - 1, s + ')', ans)

	def AllParenthesis(self, n):
		ans = []
		self.util(n, n, '', ans)
		return ans
